static bool RunUserScenario(int index){
 if(index<0||index>=(int)userScenarios.size())return false;
 const auto v=userScenarios[index];if(confirmScenarioRun&&MessageBoxW(moduleWnd,(L"Запустить сценарий «"+v.name+L"»?").c_str(),APP_NAME,MB_YESNO|MB_ICONQUESTION)!=IDYES)return false;
 if(!ApplyPowerMode(v.powerMode)){MessageBoxW(moduleWnd,L"Не удалось применить выбранный план питания.",APP_NAME,MB_OK|MB_ICONWARNING);return false;}
 preferredMode=v.powerMode;Save();if(hudVisible!=v.showHud)ToggleHud();LogEvent(L"Выполнен пользовательский сценарий: "+v.name);
 MessageBoxW(moduleWnd,L"Сценарий выполнен.",APP_NAME,MB_OK|MB_ICONINFORMATION);return true;
}
static std::wstring GpuUsageText(){
 if(!gpuQuery){if(PdhOpenQueryW(nullptr,0,&gpuQuery)!=ERROR_SUCCESS)return L"недоступно";if(PdhAddEnglishCounterW(gpuQuery,L"\\GPU Engine(*)\\Utilization Percentage",0,&gpuCounter)!=ERROR_SUCCESS){PdhCloseQuery(gpuQuery);gpuQuery=nullptr;gpuCounter=nullptr;return L"нет счётчика GPU (Windows/драйвер)";}}
 if(PdhCollectQueryData(gpuQuery)!=ERROR_SUCCESS)return L"недоступно";
 DWORD bytes=0,count=0;PDH_STATUS st=PdhGetFormattedCounterArrayW(gpuCounter,PDH_FMT_DOUBLE,&bytes,&count,nullptr);
 if(st!=static_cast<PDH_STATUS>(0x800007D2L)||bytes==0)return L"сбор данных...";
 std::vector<BYTE> buffer(bytes);auto*items=(PDH_FMT_COUNTERVALUE_ITEM_W*)buffer.data();
 if(PdhGetFormattedCounterArrayW(gpuCounter,PDH_FMT_DOUBLE,&bytes,&count,items)!=ERROR_SUCCESS)return L"недоступно";
 double total=0;for(DWORD i=0;i<count;i++)if(items[i].FmtValue.CStatus==0||items[i].FmtValue.CStatus==1)total+=items[i].FmtValue.doubleValue;
 wchar_t out[64];swprintf_s(out,L"%.0f%%",std::clamp(total,0.0,100.0));return out;
}
static void RefreshProcessList(){
 if(!processList)return;SendMessageW(processList,LB_RESETCONTENT,0,0);
 wchar_t query[256]{};if(processSearch)GetWindowTextW(processSearch,query,256);
 struct Item{std::wstring name;DWORD pid;SIZE_T mem;};std::vector<Item> items;
 HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snap==INVALID_HANDLE_VALUE)return;
 PROCESSENTRY32W pe{};pe.dwSize=sizeof(pe);
 if(Process32FirstW(snap,&pe))do{
  if(!showSystemProcesses&&(pe.th32ProcessID<=4||_wcsicmp(pe.szExeFile,L"System")==0))continue;
  if(query[0]&&wcsstr(pe.szExeFile,query)==nullptr){std::wstring a=pe.szExeFile,b=query;std::transform(a.begin(),a.end(),a.begin(),towlower);std::transform(b.begin(),b.end(),b.begin(),towlower);if(a.find(b)==std::wstring::npos)continue;}
  SIZE_T mem=0;HANDLE p=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pe.th32ProcessID);
  if(p){PROCESS_MEMORY_COUNTERS pm{};pm.cb=sizeof(pm);if(GetProcessMemoryInfo(p,&pm,sizeof(pm)))mem=pm.WorkingSetSize;CloseHandle(p);}
  items.push_back({pe.szExeFile,pe.th32ProcessID,mem});
 }while(Process32NextW(snap,&pe));CloseHandle(snap);
 if(processSortMemory)std::sort(items.begin(),items.end(),[](const Item&a,const Item&b){return a.mem>b.mem;});
 for(const auto&v:items){wchar_t line[512];swprintf_s(line,L"%-30s PID %-7lu %8.1f MB",v.name.c_str(),v.pid,(double)v.mem/1048576.0);int at=(int)SendMessageW(processList,LB_ADDSTRING,0,(LPARAM)line);SendMessageW(processList,LB_SETITEMDATA,at,v.pid);}
}
static void RefreshLogList(){
 if(!logList)return;
 SendMessageW(logList,LB_RESETCONTENT,0,0);
 std::wifstream f(logPath); std::wstring line;
 if(!f){SendMessageW(logList,LB_ADDSTRING,0,(LPARAM)L"Журнал пока пуст.");return;}
 std::vector<std::wstring> entries;while(std::getline(f,line))if(!line.empty())entries.push_back(line);size_t start=entries.size()>300?entries.size()-300:0;wchar_t q[256]{};if(logSearch)GetWindowTextW(logSearch,q,256);std::wstring filter=q;std::transform(filter.begin(),filter.end(),filter.begin(),towlower);auto add=[&](const std::wstring&v){std::wstring low=v;std::transform(low.begin(),low.end(),low.begin(),towlower);if(filter.empty()||low.find(filter)!=std::wstring::npos)SendMessageW(logList,LB_ADDSTRING,0,(LPARAM)v.c_str());};if(logNewestFirst){for(size_t i=entries.size();i>start;--i)add(entries[i-1]);}else{for(size_t i=start;i<entries.size();++i)add(entries[i]);}
 if(SendMessageW(logList,LB_GETCOUNT,0,0)==0)SendMessageW(logList,LB_ADDSTRING,0,(LPARAM)L"Журнал пока пуст.");
}
static std::wstring DiagnosticsSummary(){
 OSVERSIONINFOW os{};os.dwOSVersionInfoSize=sizeof(os);
 GetVersionExW(&os);
 MEMORYSTATUSEX mem{};mem.dwLength=sizeof(mem);GlobalMemoryStatusEx(&mem);
 ULONGLONG up=GetTickCount64()/1000;wchar_t b[1024]{};
 swprintf_s(b,L"Windows %lu.%lu (сборка %lu)\nОЗУ: %llu из %llu ГБ занято (%.0f%%)\nВремя работы системы: %llu дн. %02llu ч. %02llu мин.\nЛогических процессоров: %lu",
 os.dwMajorVersion,os.dwMinorVersion,os.dwBuildNumber,
 (unsigned long long)((mem.ullTotalPhys-mem.ullAvailPhys)/1073741824ULL),
 (unsigned long long)(mem.ullTotalPhys/1073741824ULL),(double)mem.dwMemoryLoad,
 (unsigned long long)(up/86400),(unsigned long long)((up/3600)%24),(unsigned long long)((up/60)%60),GetActiveProcessorCount(ALL_PROCESSOR_GROUPS));
 if(!diagnosticsDetailed){wchar_t shortText[512]{};swprintf_s(shortText,L"Windows %lu.%lu, ОЗУ занято: %.0f%%, GPU: %s",os.dwMajorVersion,os.dwMinorVersion,(double)mem.dwMemoryLoad,GpuUsageText().c_str());return shortText;}
 std::wstring out=b;out+=L"\nЗагрузка GPU: "+GpuUsageText();out+=L"\nFPS: доступно только для конкретного приложения/игры";out+=L"\nТемпературы CPU/GPU: нет универсального системного датчика; требуется поддержка драйвера";return out;
}
static void CopyToClipboard(HWND owner,const std::wstring& value){if(!OpenClipboard(owner))return;EmptyClipboard();SIZE_T bytes=(value.size()+1)*sizeof(wchar_t);HGLOBAL mem=GlobalAlloc(GMEM_MOVEABLE,bytes);if(mem){void*p=GlobalLock(mem);if(p){memcpy(p,value.c_str(),bytes);GlobalUnlock(mem);SetClipboardData(CF_UNICODETEXT,mem);}else GlobalFree(mem);}CloseClipboard();}
